"""Stand-in for the JusPrin server: passes every request through to the local
server on :3334, except those a rule in rules.json answers. Logs each request
(and the body of chat requests) to standin.log.

rules.json: [{"method": "DELETE", "path": "/ent/jusprin/v2/account", "status": 500,
              "body": {...}, "times": 1}]   # "path" is a prefix; "times" optional
Chat requests (/ent/jusprin/v2/responses, /messages) are never forwarded: they
get 503 unless a rule says otherwise, so no model is called.
"""
import json, os, sys, threading, urllib.request, urllib.error
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler

HERE = os.path.dirname(os.path.abspath(__file__))
UPSTREAM = "http://127.0.0.1:3334"
LOCK = threading.Lock()
USED = {}


def log(line):
    with LOCK, open(os.path.join(HERE, "standin.log"), "a") as f:
        f.write(line + "\n")


def rules():
    try:
        with open(os.path.join(HERE, "rules.json")) as f:
            return json.load(f)
    except FileNotFoundError:
        return []


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass

    def answer(self, status, body, ctype="application/json"):
        data = body if isinstance(body, bytes) else json.dumps(body).encode()
        self.send_response(status)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def handle_any(self):
        length = int(self.headers.get("Content-Length") or 0)
        body = self.rfile.read(length) if length else b""
        path = self.path
        for i, rule in enumerate(rules()):
            if rule.get("method", self.command) != self.command or not path.startswith(rule["path"]):
                continue
            if "times" in rule and USED.get(i, 0) >= rule["times"]:
                continue
            USED[i] = USED.get(i, 0) + 1
            log(f"RULE {self.command} {path} -> {rule['status']}")
            if path.startswith(("/ent/jusprin/v2/responses", "/ent/jusprin/v2/messages")):
                log("CHAT-BODY " + body.decode("utf-8", "replace")[:200000])
            return self.answer(rule["status"], rule.get("body", {}))
        if path.startswith(("/ent/jusprin/v2/responses", "/ent/jusprin/v2/messages")):
            log(f"CHAT {self.command} {path} -> 503 (not forwarded)")
            log("CHAT-BODY " + body.decode("utf-8", "replace")[:200000])
            return self.answer(503, {"error": {"code": "service_unavailable", "message": "stand-in: no model"}})
        req = urllib.request.Request(UPSTREAM + path, data=body if self.command not in ("GET", "HEAD") else None,
                                     method=self.command)
        for k, v in self.headers.items():
            if k.lower() not in ("host", "content-length", "connection", "accept-encoding"):
                req.add_header(k, v)
        try:
            with urllib.request.urlopen(req, timeout=60) as resp:
                status, data, ctype = resp.status, resp.read(), resp.headers.get("Content-Type", "application/json")
        except urllib.error.HTTPError as e:
            status, data, ctype = e.code, e.read(), e.headers.get("Content-Type", "application/json")
        log(f"PASS {self.command} {path} -> {status}")
        self.answer(status, data, ctype)

    do_GET = do_POST = do_DELETE = do_PUT = do_PATCH = handle_any


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 3399
    ThreadingHTTPServer(("127.0.0.1", port), Handler).serve_forever()

