"""Serves the app's built pages with one injected script, hands each page the
JavaScript queued for it, and records what pages report back.

Pages: /agent.html (agent page, any ?panel=...), /home.html.
Queue:   POST /queue?panel=<name>   body = JS source (an async function body)
Results: appended to results.log;  envelopes host->page to envelopes.log;
snapshots (outerHTML) written to snaps/<name>.html
"""
import json, os, sys, threading, time, urllib.parse
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler

HERE = os.path.dirname(os.path.abspath(__file__))
PAGES = {"/agent.html": sys.argv[2] + "/agent/index.html", "/home.html": sys.argv[2] + "/home/index.html"}
QUEUE, SEEN, LOCK = {}, {}, threading.Lock()

INJECT = """<script>
(function(){
  const S='http://127.0.0.1:%PORT%';
  const q=new URLSearchParams(location.search);
  const panel=(location.pathname.indexOf('home')>=0?'home':(q.get('panel')||'agent'));
  window.__panel=panel;
  const post=(path,body)=>fetch(S+path+'?panel='+panel,{method:'POST',body:typeof body==='string'?body:JSON.stringify(body)}).catch(()=>{});
  window.__post=post;
  window.__envs=[];
  let wrapped=false;
  function wrap(){
    if(wrapped||!window.__jusprinBridge)return;
    const d=window.__jusprinBridge.deliver.bind(window.__jusprinBridge);
    window.__jusprinBridge.deliver=function(raw){try{const e=typeof raw==='string'?JSON.parse(raw):raw;window.__envs.push(e);post('/env',e);}catch(x){}return d(raw);};
    wrapped=true;
  }
  window.__snap=function(name){
    const a=document.activeElement; if(a&&a.setAttribute)a.setAttribute('data-visual-focus','1');
    return post('/snap',JSON.stringify({name:name,w:window.innerWidth,h:window.innerHeight,html:document.documentElement.outerHTML}));
  };
  window.__setv=function(el,v){const p=Object.getPrototypeOf(el);const s=Object.getOwnPropertyDescriptor(p,'value').set;s.call(el,v);el.dispatchEvent(new Event('input',{bubbles:true}));};
  window.__byText=function(sel,t){return Array.from(document.querySelectorAll(sel)).find(e=>(e.textContent||'').trim().indexOf(t)>=0);};
  post('/hello',{href:location.href});
  setInterval(async()=>{
    wrap();
    try{
      const r=await fetch(S+'/next?panel='+panel); const js=await r.text();
      if(js){ let out; try{ out=await (new Function('return (async()=>{'+js+'})()'))(); }catch(e){ out='ERR '+e; } post('/result',{out:String(out)}); }
    }catch(e){}
  },400);
})();
</script>"""


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def cors(self, status=200, body=b"", ctype="text/plain"):
        self.send_response(status)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET,POST")
        self.send_header("Access-Control-Allow-Headers", "*")
        self.end_headers()

    def do_GET(self):
        u = urllib.parse.urlparse(self.path)
        qs = urllib.parse.parse_qs(u.query)
        if u.path in PAGES:
            html = open(PAGES[u.path], encoding="utf-8").read()
            html = html.replace("<head>", "<head>" + INJECT.replace("%PORT%", sys.argv[1]), 1)
            return self.cors(200, html.encode(), "text/html; charset=utf-8")
        if u.path == "/next":
            panel = qs.get("panel", [""])[0]
            with LOCK:
                SEEN[panel] = time.time()
                js = QUEUE.get(panel, []).pop(0) if QUEUE.get(panel) else ""
            return self.cors(200, js.encode())
        if u.path == "/seen":
            return self.cors(200, json.dumps({k: round(time.time() - v, 1) for k, v in SEEN.items()}).encode())
        self.cors(404)

    def do_POST(self):
        u = urllib.parse.urlparse(self.path)
        panel = urllib.parse.parse_qs(u.query).get("panel", [""])[0]
        body = self.rfile.read(int(self.headers.get("Content-Length") or 0)).decode("utf-8", "replace")
        if u.path == "/queue":
            with LOCK:
                QUEUE.setdefault(panel, []).append(body)
        elif u.path == "/env":
            with open(os.path.join(HERE, "envelopes.log"), "a") as f:
                f.write(f"{time.strftime('%H:%M:%S')} {panel} {body[:4000]}\n")
        elif u.path == "/result":
            with open(os.path.join(HERE, "results.log"), "a") as f:
                f.write(f"{time.strftime('%H:%M:%S')} {panel} {body[:20000]}\n")
        elif u.path == "/hello":
            with open(os.path.join(HERE, "results.log"), "a") as f:
                f.write(f"{time.strftime('%H:%M:%S')} {panel} HELLO {body}\n")
        elif u.path == "/snap":
            d = json.loads(body)
            os.makedirs(os.path.join(HERE, "snaps"), exist_ok=True)
            with open(os.path.join(HERE, "snaps", d["name"] + ".json"), "w") as f:
                json.dump(d, f)
        self.cors(200)


if __name__ == "__main__":
    ThreadingHTTPServer(("127.0.0.1", int(sys.argv[1])), H).serve_forever()

